<?php $v=static fn($k,$d='')=>old($k,$item->{$k}??$d); ?><div class="right_col" role="main"><h2><?= $item?'Edit':'Create' ?> Test Room</h2><div class="card shadow-sm"><div class="card-body"><?= form_open('school/admission/test-rooms/save') ?><input type="hidden" name="token" value="<?= esc($item->token??'') ?>"><div class="row"><div class="col-md-6 mb-3"><label>School *</label><select class="form-control" name="school_id"><?php foreach($schools as $s): ?><option value="<?= $s->id ?>" <?= $v('school_id')==$s->id?'selected':'' ?>><?= esc($s->name) ?></option><?php endforeach ?></select></div><div class="col-md-3 mb-3"><label>Room name *</label><input class="form-control" name="room_name" value="<?= esc($v('room_name')) ?>" required></div><div class="col-md-3 mb-3"><label>Room number *</label><input class="form-control" name="room_no" value="<?= esc($v('room_no')) ?>" required></div><div class="col-md-3 mb-3"><label>Building</label><input class="form-control" name="building" value="<?= esc($v('building')) ?>"></div><div class="col-md-3 mb-3"><label>Floor</label><input class="form-control" name="floor" value="<?= esc($v('floor')) ?>"></div><div class="col-md-2 mb-3"><label>Rows *</label><input type="number" min="1" class="form-control" name="rows_count" value="<?= esc($v('rows_count',5)) ?>"></div><div class="col-md-2 mb-3"><label>Columns *</label><input type="number" min="1" class="form-control" name="columns_count" value="<?= esc($v('columns_count',6)) ?>"></div><div class="col-md-2 mb-3"><label>Capacity *</label><input type="number" min="1" class="form-control" name="capacity" value="<?= esc($v('capacity',30)) ?>"></div><div class="col-md-3 mb-3"><label>Status</label><select class="form-control" name="status"><option value="1" <?= $v('status',1)?'selected':'' ?>>Active</option><option value="0" <?= !$v('status',1)?'selected':'' ?>>Inactive</option></select></div></div><button class="btn btn-primary">Save room</button></form></div></div></div>
